'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var strided = require( '@stdlib/blas/base/sspmv' ).ndarray;


// MAIN //

/**
* Performs the matrix-vector operation `y = alpha*A*x + beta*y`, where `alpha` and `beta` are scalars, `x` and `y` are ndarrays, and `A` is an `N` by `N` symmetric matrix supplied in packed form.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional symmetric input ndarray.
*     -   second one-dimensional input ndarray.
*     -   third one-dimensional input ndarray.
*     -   first zero-dimensional ndarray containing a scalar constant.
*     -   second zero-dimensional ndarray containing a scalar constant.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float32Vector = require( '@stdlib/ndarray/vector/float32' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float32Array = require( '@stdlib/array/float32' );
*
* var A = new ndarray( 'float32', new Float32Array( [ 1.0, 2.0, 3.0, 1.0, 2.0, 1.0 ] ), [ 6 ], [ 1 ], 0, 'row-major' );
* var x = new Float32Vector( [ 1.0, 2.0, 3.0 ] );
* var y = new Float32Vector( [ 4.0, 5.0, 6.0 ] );
*
* var alpha = scalar2ndarray( 3.0, {
*     'dtype': 'float32'
* });
* var beta = scalar2ndarray( 2.0, {
*     'dtype': 'float32'
* });
*
* var out = sspmv( [ A, x, y, alpha, beta ] );
* // returns <ndarray>[ 50.0, 40.0, 42.0 ]
*
* var bool = ( out === y );
* // returns true
*/
function sspmv( arrays ) {
	var alpha = ndarraylike2scalar( arrays[ 3 ] );
	var beta = ndarraylike2scalar( arrays[ 4 ] );
	var A = arrays[ 0 ];
	var x = arrays[ 1 ];
	var y = arrays[ 2 ];
	strided( 'row-major', 'upper', numelDimension( x, 0 ), alpha, getData( A ), getOffset( A ), getData( x ), getStride( x, 0 ), getOffset( x ), beta, getData( y ), getStride( y, 0 ), getOffset( y ) );
	return y;
}


// EXPORTS //

module.exports = sspmv;
